CREATE DATABASE IF NOT EXISTS doctorconnect CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;USE doctorconnect;SET FOREIGN_KEY_CHECKS=0;DROP TABLE IF EXISTS appointments;DROP TABLE IF EXISTS doctors;DROP TABLE IF EXISTS departments;DROP TABLE IF EXISTS users;SET FOREIGN_KEY_CHECKS=1;CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(150) NOT NULL UNIQUE,phone VARCHAR(30) NOT NULL,password VARCHAR(255) NOT NULL,role ENUM('patient','doctor','receptionist','admin') NOT NULL DEFAULT 'patient',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);CREATE TABLE departments(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) UNIQUE NOT NULL);CREATE TABLE doctors(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT UNIQUE NOT NULL,department_id INT NOT NULL,specialization VARCHAR(150) NOT NULL,fee DECIMAL(10,2) NOT NULL,available_days VARCHAR(150) NOT NULL,start_time TIME NOT NULL,end_time TIME NOT NULL,room VARCHAR(30) NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(department_id) REFERENCES departments(id));CREATE TABLE appointments(id INT AUTO_INCREMENT PRIMARY KEY,patient_id INT NOT NULL,doctor_id INT NOT NULL,appointment_date DATE NOT NULL,appointment_time TIME NOT NULL,serial_no INT NOT NULL,source ENUM('online','walk-in') DEFAULT 'online',status ENUM('pending','checked-in','completed','cancelled','no-show') DEFAULT 'pending',diagnosis VARCHAR(255),visit_note TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(patient_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(doctor_id) REFERENCES doctors(id) ON DELETE CASCADE,UNIQUE KEY doctor_slot(doctor_id,appointment_date,appointment_time));INSERT INTO departments(name) VALUES('Cardiology'),('Medicine'),('Neurology'),('Pediatrics'),('Dermatology');INSERT INTO users(name,email,phone,password,role) VALUES('System Admin','admin@doctorconnect.com','01700000001','$2y$12$2GTTDFO1QSlAP3W0eU6A2.EbnPHJIeHR0Nfh586BAde60PdxKqcka','admin'),('Tasnim Khatun','doctor@doctorconnect.com','01700000002','$2y$12$cE7GrmSCK5izyJb2mU9UFOAvW9uoKKQZwqg0.NvS5.fl8OEsIjAkW','doctor'),('Nilima Salam','patient@doctorconnect.com','01700000003','$2y$12$QBGuIJYkU0gCfO.ceYYlHOOUPMebVa47TIEOKHl1nXF/OMdvC/2Re','patient'),('Uzma Reception','reception@doctorconnect.com','01700000004','$2y$12$g/rX.iumhzk2MBQ/MESLCeU5sLVzjoZqhwQqBB.hpYZFbCYRXTKOe','receptionist');INSERT INTO doctors(user_id,department_id,specialization,fee,available_days,start_time,end_time,room) VALUES(2,1,'Cardiologist',1000,'Saturday, Monday, Wednesday','17:00','20:00','201');INSERT INTO appointments(patient_id,doctor_id,appointment_date,appointment_time,serial_no,source,status) VALUES(3,1,DATE_ADD(CURDATE(),INTERVAL 1 DAY),'17:00',1,'online','pending');